// App code: switching the selected tab and showing its panel.
import type { Example } from "../example.ts"
import { tabBadge } from "./tab-badge.ts"
import { html, nothing, type TemplateResult } from "lit-html"

export type TabState = "selected" | "unselected"

export type TabProps = {
  id: string
  panel: string
  label: string
  state: TabState
  count?: string
  countLoading?: boolean
  onClick?: (event: MouseEvent) => void
  class?: string
}

// The tab's look only. No motion (apps animate their own tabs).
const look =
  "inline-flex min-h-tab items-center gap-1.5 whitespace-nowrap rounded-lg px-3.5 text-sm font-medium focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-accent/50 focus-visible:ring-offset-0"

const states: Record<TabState, string> = {
  selected: "bg-surface text-fg shadow-sm ring-1 ring-line",
  unselected: "text-muted hover:text-fg",
}

/** Apps put these classes on each tab; pick the state of the current one. */
export function tabClass(state: TabState): string {
  return `${look} ${states[state]}`
}

function counter(props: TabProps): TemplateResult | typeof nothing {
  if (props.countLoading === true) {
    return html`<span class="ml-2 inline-block w-6 h-4 bg-subtle rounded-full animate-pulse motion-reduce:animate-none" aria-hidden="true"></span><span class="sr-only"> (loading count)</span>`
  }
  if (props.count === undefined) return nothing
  return html`<span>${tabBadge({ count: props.count, variant: "primary" })}</span>`
}

export function tab(props: TabProps): TemplateResult {
  const selected = props.state === "selected"
  const classes = [tabClass(props.state), "cursor-pointer transition-colors duration-fast ease-standard"]
  if (props.class !== undefined) classes.push(props.class)
  return html`<button
    type="button"
    role="tab"
    id=${props.id}
    class=${classes.join(" ")}
    aria-selected=${selected ? "true" : "false"}
    aria-controls=${props.panel}
    tabindex=${selected ? "0" : "-1"}
    @click=${props.onClick}
  >${props.label}${counter(props)}</button>`
}

export const examples: Example[] = [
  { label: "selected", render: () => tab({ id: "albums-tab", panel: "albums-panel", label: "Albums", state: "selected" }) },
  { label: "unselected", render: () => tab({ id: "people-tab", panel: "people-panel", label: "People", state: "unselected" }) },
  { label: "unselected · count", render: () => tab({ id: "requests-tab", panel: "requests-panel", label: "Requests", state: "unselected", count: "3" }) },
  { label: "selected · count", render: () => tab({ id: "requests-tab", panel: "requests-panel", label: "Requests", state: "selected", count: "3" }) },
  { label: "unselected · loading count", render: () => tab({ id: "requests-tab", panel: "requests-panel", label: "Requests", state: "unselected", countLoading: true }) },
]
